    /** Keep the state a claim and a person are in now, with the sheet's today, as a save would: they
     *  were brought onto the sheet. */
    public void claimKept(Long claimId) {
        jdbc.update(HistoryListener.CLAIM, claimId);
    }

    public void personKept(Long personId) {
        jdbc.update(HistoryListener.PERSON, personId);
    }

    /** Keep the state every claim, person, rate, grade, dated setting and period of the sheet is in
     *  now, and its policy date, with the sheet's today: the sheet was made whole at once (a clone). */
    public void sheetKept(String sheetId) {
        jdbc.query("SELECT id FROM claim WHERE sheet_id = ? ORDER BY id", (rs, n) -> rs.getLong("id"), sheetId)
                .forEach(this::claimKept);
        jdbc.query("SELECT id FROM person WHERE sheet_id = ? ORDER BY id", (rs, n) -> rs.getLong("id"), sheetId)
                .forEach(this::personKept);
        jdbc.update("INSERT INTO rate_history (sheet_id, grade, from_date, to_date, rate, version, forward_after,"
                + " made_on) SELECT r.sheet_id, r.grade, r.from_date, r.to_date, r.rate, r.version, r.forward_after, s.today"
                + " FROM rate r JOIN sheet s ON s.id = r.sheet_id WHERE r.sheet_id = ? ORDER BY r.id", sheetId);
        jdbc.update("INSERT INTO person_grade_history (sheet_id, person_id, grade, from_date, made_on)"
                + " SELECT g.sheet_id, g.person_id, g.grade, g.from_date, s.today"
                + " FROM person_grade g JOIN sheet s ON s.id = g.sheet_id WHERE g.sheet_id = ? ORDER BY g.id", sheetId);
        jdbc.update("INSERT INTO sheet_setting_value_history (sheet_id, setting_key, from_date, setting_value,"
                + " setting_text, made_on) SELECT v.sheet_id, v.setting_key, v.from_date, v.setting_value, v.setting_text, s.today"
                + " FROM sheet_setting_value v JOIN sheet s ON s.id = v.sheet_id WHERE v.sheet_id = ? ORDER BY v.id",
                sheetId);
        jdbc.update("INSERT INTO period_history (period_id, sheet_id, name, from_date, to_date, closed, soft_closed,"
                + " closed_total, person_totals, made_on) SELECT p.id, p.sheet_id, p.name, p.from_date, p.to_date,"
                + " p.closed, p.soft_closed, p.closed_total, '', s.today FROM period p JOIN sheet s ON s.id = p.sheet_id"
                + " WHERE p.sheet_id = ? ORDER BY p.id", sheetId);
        policyDateSet(sheetId);
    }

    /** Keep a user starting or stopping watching a person, with the sheet's today. */
    public void watchSet(String sheetId, Long personId, String user, boolean watched) {
        jdbc.update("INSERT INTO person_watch_history (sheet_id, person_id, user_name, watched, made_on)"
                + " SELECT id, ?, ?, ?, today FROM sheet WHERE id = ?", personId, user, watched, sheetId);
    }

    /** A period as it stood at the end of a day. */
    public record PeriodThen(Long id, String name, LocalDate from, LocalDate to, boolean closed, boolean softClosed,
            BigDecimal closedTotal, Map<Long, BigDecimal> personTotals) {
    }

    /** Keep a period's state as it is now saved, with the sheet's today. */
    public void periodSaved(Long periodId, String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
            boolean softClosed, BigDecimal closedTotal, Map<Long, BigDecimal> personTotals) {
        String totals = String.join(",", personTotals.entrySet().stream()
                .map(e -> e.getKey() + "=" + e.getValue().toPlainString()).toList());
        jdbc.update("INSERT INTO period_history (period_id, sheet_id, name, from_date, to_date, closed, soft_closed,"
                        + " closed_total, person_totals, made_on) SELECT ?, id, ?, ?, ?, ?, ?, ?, ?, today FROM sheet"
                        + " WHERE id = ?",
                periodId, name, from, to, closed, softClosed, closedTotal, totals, sheetId);
    }

    /** The sheet's periods as they stood at the end of a day, by period id; a period saved only after
     *  it, or before their states were kept, is absent. */
    public Map<Long, PeriodThen> periods(String sheetId, LocalDate day) {
        Map<Long, PeriodThen> then = new LinkedHashMap<>();
        jdbc.query("SELECT * FROM period_history WHERE sheet_id = ? AND made_on <= ? ORDER BY id", (rs, n) -> {
            Map<Long, BigDecimal> totals = new LinkedHashMap<>();
            String kept = rs.getString("person_totals");
            if (!kept.isEmpty()) {
                for (String pair : kept.split(",")) {
                    String[] parts = pair.split("=");
                    totals.put(Long.valueOf(parts[0]), new BigDecimal(parts[1]));
                }
            }
            return new PeriodThen(rs.getLong("period_id"), rs.getString("name"),
                    rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class),
                    rs.getBoolean("closed"), rs.getBoolean("soft_closed"), rs.getBigDecimal("closed_total"), totals);
        }, sheetId, day).forEach(period -> then.put(period.id(), period));
        return then;
    }

    /** Keep a value set for a sheet setting that is not dated (null: blank), with the sheet's today. */
    public void settingSet(String sheetId, String key, String value) {
        jdbc.update("INSERT INTO sheet_setting_history (sheet_id, setting_key, setting_value, made_on)"
                + " SELECT id, ?, ?, today FROM sheet WHERE id = ?", key, value, sheetId);
-- What the sheet held as of a day: each change that bears on a claim's figures is kept with the
-- sheet's today when it was made, so a statement can be taken as of a past day (every change made
-- while the sheet's today was on or before it counts, every later one does not).

-- The sheet's today when the person was added; null for one added before this was kept.
ALTER TABLE person ADD COLUMN added_on DATE;

-- The sheet's today when the hold was put on; null for one put on before this was kept.
ALTER TABLE person_hold ADD COLUMN made_on DATE;

-- Each rate as it was set: the grade's rate from its from-date, as of the sheet's today then.
CREATE TABLE rate_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    grade VARCHAR(1) NOT NULL,
    from_date DATE,
    to_date DATE,
    rate DECIMAL(7, 2) NOT NULL,
    made_on DATE NOT NULL
);
CREATE INDEX rate_history_sheet ON rate_history (sheet_id, grade, id);

-- Each grade a person was given from a from-date, as of the sheet's today then.
CREATE TABLE person_grade_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL REFERENCES person (id),
    grade VARCHAR(1) NOT NULL,
    from_date DATE,
    made_on DATE NOT NULL
);
CREATE INDEX person_grade_history_person ON person_grade_history (person_id, id);

-- Each value recorded for a dated setting from a from-date, as of the sheet's today then.
CREATE TABLE sheet_setting_value_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    setting_key VARCHAR(40) NOT NULL,
    from_date DATE NOT NULL,
    setting_value DECIMAL(12, 2),
    made_on DATE NOT NULL
);
CREATE INDEX sheet_setting_value_history_key ON sheet_setting_value_history (sheet_id, setting_key, id);

-- Each policy date set (null: blank), as of the sheet's today then.
CREATE TABLE sheet_policy_date_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    policy_date DATE,
    made_on DATE NOT NULL
);
CREATE INDEX sheet_policy_date_history_sheet ON sheet_policy_date_history (sheet_id, id);

-- Each state a claim was saved in, as of the sheet's today then.
CREATE TABLE claim_history (
    id BIGINT AUTO_INCREMENT PRIMARY KEY,
    claim_id BIGINT NOT NULL REFERENCES claim (id),
    sheet_id VARCHAR(200) NOT NULL REFERENCES sheet (id),
    person_id BIGINT NOT NULL,
    amount DECIMAL(12, 2) NOT NULL,
    claim_date DATE NOT NULL,
    due_by DATE NOT NULL,
    status VARCHAR(20) NOT NULL,
    settled_due DECIMAL(12, 2),
    stated BOOLEAN NOT NULL,
    stated_due DECIMAL(12, 2),
    corrects_number VARCHAR(255),
    deferred_until DATE,
    made_on DATE NOT NULL
);
CREATE INDEX claim_history_claim ON claim_history (claim_id, id);
